function Badge({ variant = 'info', children }) {
  return (
    <span
      className={cn(
        'px-2 py-0.5 rounded text-sm font-medium',
        variant === 'info'    && 'bg-blue-100 text-blue-800',
        variant === 'success' && 'bg-green-100 text-green-800',
        variant === 'danger'  && 'bg-red-100 text-red-800',
      )}
    >
      {children}
    </span>
  );
}

